INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1196237', 'Proto-Elamite period', 'The Proto-Elamite period, also known as Susa III, is a chronological era in the ancient history of the area of Elam, dating from c. 3100 BC to 2700 BC. In archaeological terms this corresponds to the late Banesh period. Proto-Elamite sites are recognized as the oldest civilization in Iran.', -3100, NULL, NULL, -2700, NULL, NULL, 'year', '3100 BCE – 2700 BCE', 59, 'https://en.wikipedia.org/wiki/Proto-Elamite_(period)'),
  ('Q3436196', 'Medo-Persian conflict', 'The Medo-Persian conflict was a campaign led by the Median king Astyages against Persis in the mid 6th-century BCE. Classical sources claim that Persis had been a vassal of the Median kingdom that revolted against Median rule, but this is not confirmed by contemporary evidence. After some battles the Persians led by Cyrus the Great emerged victorious, subsequently conquering Median territories and establishing the Achaemenid Empire.', -553, NULL, NULL, -550, NULL, NULL, 'year', '553 BCE – 550 BCE', 55, 'https://en.wikipedia.org/wiki/Medo-Persian_conflict'),
  ('Q112016', 'Battle of the Persian Gate on the Mountain', 'The Battle of the Persian Gate took place as part of the Wars of Alexander the Great. In the winter of 330 BC, Ariobarzanes of Persis led a last stand with his outnumbered Persian army at the Persian Gate, near Persepolis, and held back the Macedonian army for approximately a month.', -330, 1, 20, NULL, NULL, NULL, 'day', '20 January 330 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_the_Persian_Gate'),
  ('Q2887977', 'Battle of Hormozdgan', 'The Battle of Hormozdgan (also spelled Hormizdagan and Hormozgan) was the climactic battle between the Arsacid and the Sasanian dynasties that took place on 28 April 224. The Sasanian victory broke the power of the Parthian dynasty, effectively ending almost five centuries of Parthian rule in Iran, and marking the official start of the Sasanian era.', 224, 4, 28, NULL, NULL, NULL, 'day', '28 April 224', 56, 'https://en.wikipedia.org/wiki/Battle_of_Hormozdgan'),
  ('Q734700', 'Battle of Avarayr', 'The Battle of Avarayr (Armenian: Ավարայրի ճակատամարտ, romanized: Avarayri chakatamart) was fought on 26 May 451 on the Avarayr Plain in Vaspurakan between a Christian Armenian army under Vardan Mamikonian and Sassanid Persia. It is considered one of the first battles in defense of the Christian faith.', 451, 5, 26, NULL, NULL, NULL, 'day', '26 May 451', 65, 'https://en.wikipedia.org/wiki/Battle_of_Avarayr'),
  ('Q603549', 'Battle of Nahāvand', 'The Battle of Nahavand (Arabic: معركة نهاوند Maʿrakah Nahāwand, Persian: نبرد نهاوند Nabard-e Nahâvand), also spelled Nihavand or Nahawand, was fought in 642 between the Rashidun Muslim forces under An-Numan ibn Muqarrin and Sasanian army under King Yazdegerd III. Yazdegerd escaped to the Merv area, but was unable to raise another substantial army. The battle ended in a victory for the Rashidun Caliphate and the Sasanids consequently lost the surrounding cities including Spahan (Isfahan).', 642, NULL, NULL, NULL, NULL, NULL, 'year', '642', 66, 'https://en.wikipedia.org/wiki/Battle_of_Nahavand'),
  ('Q4087410', 'Battle of Marj Ardabil', 'The Battle of Marj Ardabil was a military engagement between the Umayyads and the Khazars in AD 730. A Khazar army led by Barjik, the Khazar Khagan, inflicted a catastrophic defeat on the Umayyads, killing the majority of the army and its leader, al-Jarrah ibn Abdallah.', 730, 12, 9, NULL, NULL, NULL, 'day', '9 December 730', 51, 'https://en.wikipedia.org/wiki/Battle_of_Marj_Ardabil'),
  ('Q3544130', '856 Damghan earthquake', 'The Damghan earthquake or the Qumis earthquake occurred on 22 December 856 (242 AH) in Khorasan province, Abbasid Caliphate. The earthquake had an estimated magnitude of 7.9, and a maximum intensity of X (Extreme) on the Mercalli intensity scale.', 856, 12, 22, NULL, NULL, NULL, 'day', '22 December 856', 56, 'https://en.wikipedia.org/wiki/856_Damghan_earthquake'),
  ('Q759988', 'Zanj Rebellion', 'The Zanj Rebellion (Arabic: ثورة الزنج Thawrat al-Zanj / Zinj) was a major revolt against the Abbasid Caliphate, which took place from 869 until 883. Begun near the city of Basra in present-day southern Iraq and led by one Ali ibn Muhammad, the insurrection involved both enslaved and freed Africans (collectively termed "Zanj" in this case) exported in the Indian Ocean slave trade and transported to slavery in the Abbasid Caliphate in the Middle East, principally to drain the region''s salt marshes.', 869, NULL, NULL, 883, NULL, NULL, 'year', '869–883', 64, 'https://en.wikipedia.org/wiki/Zanj_Rebellion'),
  ('Q92987578', 'Mongol campaign against the Nizaris', 'The Mongols launched a campaign against the Nizari Ismaili state in 1253 after invading the Khwarazmian Empire and a series of Nizari–Mongol conflicts. The campaign was ordered by the Great Khan Möngke and was led by his brother, Hülegü.', 1253, NULL, NULL, 1270, NULL, NULL, 'year', '1253–1270', 50, 'https://en.wikipedia.org/wiki/Mongol_campaign_against_the_Nizaris'),
  ('Q745110', 'Battle of Chaldiran', 'The Battle of Chaldiran (Persian: جنگ چالدران; Turkish: Çaldıran Savaşı) took place on 23 August 1514 and ended with a decisive victory for the Ottoman Empire over the Safavid Empire. As a result, the Ottomans annexed Eastern Anatolia and Upper Mesopotamia from Safavid Iran.', 1514, 8, 23, NULL, NULL, NULL, 'day', '23 August 1514', 72, 'https://en.wikipedia.org/wiki/Battle_of_Chaldiran'),
  ('Q3296937', 'Battle of Gulnabad', 'The Battle of Gulnabad (Pashto: د ګلون اباد جګړه, romanized: Dh Gulonābād Jaghrha; Persian: نبرد گلون‌آباد, romanized: Nabard-e Golūnābād) was fought between the military forces from the Hotak dynasty and the army of the Safavid Empire on Sunday, March 8, 1722. It further cemented the eventual fall of the Safavid dynasty, which had been declining for decades.', 1722, 3, 8, NULL, NULL, NULL, 'day', '8 March 1722', 53, 'https://en.wikipedia.org/wiki/Battle_of_Gulnabad'),
  ('Q1368440', 'Persian Constitutional Revolution', 'The Persian Constitutional Revolution (Persian: مشروطیت, romanized: Mašrutiat, or انقلاب مشروطه Enqelâb-e Mašrute), also known as the Constitutional Revolution of Iran, took place between 1905 and 1911 during the Qajar era. The revolution led to the establishment of a parliament in Iran (Persia), and has been called an "epoch-making episode in the modern history of Persia".', 1905, NULL, NULL, 1911, NULL, NULL, 'year', '1905–1911', 69, 'https://en.wikipedia.org/wiki/Persian_Constitutional_Revolution'),
  ('Q764038', 'Jungle Movement of Gilan', 'The Jangal (Forest or Jungle) Movement (Persian: جنبش جنگل) was a rebellion against the monarchist central government of the Sublime State of Iran in Gilan, which lasted from 1915 to 1921.', 1915, 10, NULL, 1920, 6, 5, 'month', 'October 1915 – 5 June 1920', 51, 'https://en.wikipedia.org/wiki/Jungle_Movement_of_Gilan'),
  ('Q590605', 'insurgency in Balochistan', 'An ongoing insurgency in Pakistan''s Balochistan province and Iran''s Sistan and Baluchestan province is fought between Baloch nationalist separatist groups, Islamist militants, and the governments of Pakistan and Iran. The conflict is rooted in long-standing grievances over political marginalisation, economic underdevelopment, enforced disappearances, and the control of Balochistan''s natural resources.', 1948, NULL, NULL, NULL, NULL, NULL, 'year', '1948', 65, 'https://en.wikipedia.org/wiki/Insurgency_in_Balochistan'),
  ('Q1068139', 'White Revolution', 'The White Revolution (Persian: انقلاب سفید, romanized: Enqelâb-e Sefid) or the Shah and People Revolution (Persian: انقلاب شاه و مردم, romanized: Enqelâb-e Šâh o Mardom) was a series of reforms to modernize the Imperial State of Iran launched on 26 January 1963 by the Shah, Mohammad Reza Pahlavi, and ended with his overthrow in 1979. Among the elements of the Revolution were land reform where landlords were compensated for their land by shares of privatized state-owned factories, expanded road, rail, and air network, dam and irrigation projects, work to eradicate diseases such as malaria,…', 1963, NULL, NULL, 1979, NULL, NULL, 'year', '1963–1979', 70, 'https://en.wikipedia.org/wiki/White_Revolution'),
  ('Q126065', 'Iranian Revolution', 'The Iranian Revolution, also known as the Islamic Revolution, culminated in the overthrow of the Pahlavi dynasty in 1979. The revolution led to the replacement of the Imperial State of Iran by the Islamic Republic of Iran, as the monarchical government of Shah Mohammad Reza Pahlavi was superseded by Ruhollah Khomeini, an Islamist cleric who had headed one of the rebel factions, and became the country’s supreme leader.The ousting of Mohammad Reza Pahlavi, the last Shah of Iran, formally marked the end of Iran''s historical monarchy.', 1970, NULL, NULL, 1979, 2, NULL, 'decade', '1970s – February 1979', 88, 'https://en.wikipedia.org/wiki/Iranian_Revolution'),
  ('Q4231692', 'Iranian Islamic Republic referendum, March 1979', 'A referendum on establishing an Islamic republic was held in Iran on 30 and 31 March 1979. It took place in the aftermath of the Iranian Revolution, which led to the overthrow of the Pahlavi dynasty on 11 February 1979 and the rise of Ayatollah Ruhollah Khomeini as Iran''s de facto leader.', 1979, 3, 31, NULL, NULL, NULL, 'day', '31 March 1979', 55, 'https://en.wikipedia.org/wiki/1979_Iranian_Islamic_Republic_referendum'),
  ('Q5955315', 'International Women''s Day in 1979 in Iran', 'On International Women''s Day on 8 March 1979, a women''s march took place in Tehran, Iran. The march was originally intended to celebrate the International Women''s Day, but transformed into massive protests against the changes taking place in women''s rights during the Iranian Revolution, specifically the introduction of mandatory hijab (veiling), which had been announced the day before.', 1979, 3, 8, NULL, NULL, NULL, 'day', '8 March 1979', 53, 'https://en.wikipedia.org/wiki/1979_International_Women''s_Day_protests_in_Tehran'),
  ('Q815104', 'Siege of Abadan', 'The siege of Abadan was the encirclement of the city by Iraqi forces beginning in November 1980. The city had already been under almost daily bombardment since the early days of the war, which began the previous September.', 1980, 11, 6, 1981, 9, 27, 'day', '6 November 1980 – 27 September 1981', 53, 'https://en.wikipedia.org/wiki/Siege_of_Abadan'),
  ('Q1132313', 'Battle of Khorramshahr', 'The First Battle of Khorramshahr was a major battle in the Iran–Iraq War, beginning shortly after the Iraqi invasion of Iran in September 1980. Amidst the gruelling urban warfare in and around the city, Khorramshahr came to be referred to by the Iranians as Khuninshahr (Persian: خونین شهر, lit. ''City of Blood''), as both sides had suffered heavy casualties in combat.', 1980, 9, 22, 1980, 11, 10, 'day', '22 September 1980 – 10 November 1980', 53, 'https://en.wikipedia.org/wiki/Battle_of_Khorramshahr_(1980)'),
  ('Q2254354', 'Iran Air Flight 291', 'Iran Air Flight 291 was a charter flight from Mashad Airport to Tehran-Mehrabad Airport. On 21 January 1980, the Boeing 727-86 during its approach crashed on the Tehran-Mehrabad runway 29 in foggy and snowy weather conditions, killing all 128 people on board.', 1980, 1, 21, NULL, NULL, NULL, 'day', '21 January 1980', 55, 'https://en.wikipedia.org/wiki/Iran_Air_Flight_291'),
  ('Q1570898', 'Battle of Dezful', 'Operation Nasr, also known as Operation Hoveyzeh, was a major battle in the Iran–Iraq War fought in early January 1981. It was the biggest tank battle of the war.', 1981, NULL, NULL, 1981, 1, 9, 'year', '1981', 51, 'https://en.wikipedia.org/wiki/Operation_Nasr'),
  ('Q814223', 'Liberation of Khorramshahr', 'The Second Battle of Khorramshahr, also known in Iran as the Liberation of Khorramshahr (Persian: آزادسازی خرمشهر, romanized: Âzâdsâzī-ye Khorramshahr) was the Iranian recapture of the city of Khorramshahr on 24 May 1982, during the Iran–Iraq War. The city had been captured by the Iraqis earlier in the war, on 26 October 1980, shortly after the Iraqi invasion of Iran.', 1982, 4, 24, 1982, 5, 24, 'day', '24 April 1982 – 24 May 1982', 51, 'https://en.wikipedia.org/wiki/Battle_of_Khorramshahr_(1982)'),
  ('Q603134', '1990 Manjil–Rudbar earthquake', 'The 1990 Manjil–Rudbar earthquake (Persian: زمین‌لرزه ۱۳۶۹ رودبار و منجیل; Gilaki: زلزله رودبار) occurred on Thursday, 21 June 1990 at 00:30:14 local time in the Caspian Sea region of northern Iran. The shock had a moment magnitude of 7.4 and a Mercalli Intensity of X (Extreme).', 1990, 6, 20, NULL, NULL, NULL, 'day', '20 June 1990', 53, 'https://en.wikipedia.org/wiki/1990_Manjil%E2%80%93Rudbar_earthquake'),
  ('Q973979', '1997 Qayen earthquake', 'An earthquake struck northern Iran''s Khorasan Province in the vicinity of Qaen on May 10, 1997, at 07:57 UTC (12:57 local time). The largest in the area since 1990, the earthquake registered 7.3 on the moment magnitude scale and was centered approximately 270 kilometers (170 mi) south of Mashhad on the village of Ardekul.', 1997, 5, 10, NULL, NULL, NULL, 'day', '10 May 1997', 52, 'https://en.wikipedia.org/wiki/1997_Qayen_earthquake'),
  ('Q11737216', 'Iran Air Tours Flight 956', 'Iran Air Tours Flight 956 was a Tupolev Tu-154M which crashed 230 miles (370 km) south-west of Tehran on 12 February 2002. During a non precision approach to runway 11 of Khorramabad Airport, the airliner impacted the Kuh-e Sefid Mountain at an altitude of 9,100 feet (2,800 m), three nautical miles (5.6 km; 3.5 mi) left of the runway centerline.', 2002, 2, 12, NULL, NULL, NULL, 'day', '12 February 2002', 50, 'https://en.wikipedia.org/wiki/Iran_Airtour_Flight_956'),
  ('Q1990627', '2003 Bam earthquake', 'An earthquake struck the Kerman province of southeastern Iran at 01:56 UTC (5:26 am Iran Standard Time) on December 26, 2003. The Mw 6.6 (Ms 6.8–7.0) strike-slip shock had a maximum Mercalli intensity of X (Extreme).', 2003, 12, 26, NULL, NULL, NULL, 'day', '26 December 2003', 62, 'https://en.wikipedia.org/wiki/2003_Bam_earthquake'),
  ('Q842831', 'Caspian Airlines Flight 7908', 'Caspian Airlines Flight 7908 was a scheduled commercial flight from Tehran, Iran, to Yerevan, Armenia, that crashed near the village of Jannatabad, outside the city of Qazvin in north-western Iran, on 15 July 2009. All 153 passengers and 15 crew members on board died.', 2009, 7, 15, NULL, NULL, NULL, 'day', '15 July 2009', 64, 'https://en.wikipedia.org/wiki/Caspian_Airlines_Flight_7908'),
  ('Q2020397', 'Aria Air Flight 1525', 'Aria Air Flight 1525 was a scheduled Iranian domestic flight which crashed on landing at Mashhad International Airport, Mashhad, Iran, on 24 July 2009.', 2009, 7, 24, NULL, NULL, NULL, 'day', '24 July 2009', 51, 'https://en.wikipedia.org/wiki/Aria_Air_Flight_1525'),
  ('Q854206', '2009 Iranian presidential election protests', 'After incumbent president Mahmoud Ahmadinejad declared victory in the 2009 Iranian presidential election, protests broke out in major cities across Iran in support of opposition candidates Mir-Hossein Mousavi and Mehdi Karroubi. The protests continued until 2010, and were titled the Iranian Green Movement by their proponents, reflecting Mousavi''s campaign theme, and Persian Awakening, Persian Spring or Green Revolution.', 2010, 2, 11, 2010, 12, 7, 'day', '11 February 2010 – 7 December 2010', 61, 'https://en.wikipedia.org/wiki/2009_Iranian_presidential_election_protests'),
  ('Q947960', '2011–2012 Iranian protests', 'The 2011–2012 protests in Iran were a series of demonstrations in Iran which began on 14 February 2011, called "The Day of Rage". The protests followed the 2009–2010 Iranian election protests and were influenced by other concurrent protests in the region.', 2010, NULL, NULL, 2012, 2, 14, 'decade', '2010s – 14 February 2012', 52, 'https://en.wikipedia.org/wiki/2011%E2%80%932012_Iranian_protests'),
  ('Q189079', 'Van earthquake of 2011', 'The 2011 Van earthquakes occurred in eastern Turkey near the city of Van. The first earthquake happened on 23 October at 13:41 local time.', 2011, 10, 23, NULL, NULL, NULL, 'day', '23 October 2011', 70, 'https://en.wikipedia.org/wiki/2011_Van_earthquakes'),
  ('Q951088', 'Iran Air Flight 277', 'Iran Air Flight 277 was a scheduled Iran Air flight from Mehrabad International Airport, Tehran to Urmia Airport, Iran. On 9 January 2011, the Boeing 727 serving the flight crashed after an aborted approach to Urmia Airport in poor weather.', 2011, 1, 9, NULL, NULL, NULL, 'day', '9 January 2011', 63, 'https://en.wikipedia.org/wiki/Iran_Air_Flight_277'),
  ('Q1362436', '2011 attack on the British Embassy in Iran', 'On 29 November 2011, a crowd of Iranian protesters gathered outside the British Embassy in the central Jomhouri district of Tehran before a faction of hardline students and demonstrators stormed the compound and a separate British diplomatic site in northern Tehran known as Gholhak Garden. The attack came several days after Iran''s parliament voted to downgrade diplomatic ties with the UK in retaliation for Britain''s role in pushing stringent new financial sanctions targeting the Central Bank of Iran and broader economy, measures tied directly to an International Atomic Energy Agency report…', 2011, 11, 29, NULL, NULL, NULL, 'day', '29 November 2011', 52, 'https://en.wikipedia.org/wiki/2011_British_Embassy_in_Iran_attack'),
  ('Q10798381', '2013 Bushehr earthquake', 'The 2013 Bushehr earthquake occurred with a moment magnitude of 6.3 on April 9 in Iran. The shock''s epicenter was in the province of Bushehr, near the city of Khvormuj and the towns of Kaki and Shonbeh.', 2013, 4, 9, NULL, NULL, NULL, 'day', '9 April 2013', 52, 'https://en.wikipedia.org/wiki/2013_Bushehr_earthquake'),
  ('Q11158136', '2013 Sistan and Baluchestan earthquake', 'The 2013 Saravan earthquake occurred with a moment magnitude of 7.7 at 15:14 pm IRDT (UTC+4:30) on 16 April. The shock struck a mountainous area between the cities of Saravan and Khash in Sistan and Balochistan province, Iran, close to the border with Pakistan, with a duration of about 25 seconds.', 2013, 4, 16, NULL, NULL, NULL, 'day', '16 April 2013', 61, 'https://en.wikipedia.org/wiki/2013_Saravan_earthquake'),
  ('Q14944216', '2013 Balochistan earthquakes', 'The 2013 Balochistan earthquakes were the deadliest to affect Pakistan since 2005. The mainshock, occurring on 24 September, had a moment magnitude of 7.8 and maximum Mercalli intensity of IX (Violent).', 2013, 9, 24, NULL, NULL, NULL, 'day', '24 September 2013', 59, 'https://en.wikipedia.org/wiki/2013_Balochistan_earthquakes'),
  ('Q17496200', 'Sepahan Airlines Flight 5915', 'Sepahan Airlines Flight 5915 was a scheduled domestic passenger flight from Iranian capital Tehran Mehrabad International Airport to Tabas, South Khorasan province, Iran. On 10 August 2014, the HESA IrAn-140 twin turboprop serving the flight crashed shortly after takeoff from Mehrabad International Airport, falling into a boulevard near the Azadi Stadium.', 2014, 8, 10, NULL, NULL, NULL, 'day', '10 August 2014', 57, 'https://en.wikipedia.org/wiki/Sepahan_Airlines_Flight_5915'),
  ('Q30147595', '2017 Tehran attacks', 'A series of two simultaneous terrorist attacks were carried out on 7 June 2017 by five terrorists belonging to the Islamic State of Iraq and the Levant (ISIL) against the Iranian Parliament building and the Mausoleum of Ruhollah Khomeini, both in Tehran, Iran, leaving 17 civilians dead and 43 wounded. The shootings were the first terrorist attacks in Tehran in more than a decade, and the first major terror attack in the country since the 2010 Zahedan bombings.', 2017, 6, 7, NULL, NULL, NULL, 'day', '7 June 2017', 67, 'https://en.wikipedia.org/wiki/2017_Tehran_attacks'),
  ('Q43041167', '2017 Iran–Iraq earthquake', 'On 12 November 2017 at 18:18 UTC (21:48 Iran Standard Time, 21:18 Arabia Standard Time), an earthquake with a moment magnitude of 7.4 occurred on the Iran–Iraq border, with the Iraqi Kurdish city of Halabja, and the Kurdish dominated places of Ezgeleh, Salas-e Babajani County, Kermanshah province in Iran, closest to the epicentre, 30 kilometres (19 mi) south of the city of Halabja, Iraqi Kurdistan. It was felt as far away as Israel and the United Arab Emirates.', 2017, 11, 12, NULL, NULL, NULL, 'day', '12 November 2017', 68, 'https://en.wikipedia.org/wiki/2017_Iran%E2%80%93Iraq_earthquake'),
  ('Q46999835', '2017–2018 Iranian protests', 'Public protests took place in several cities in Iran beginning on 28 December 2017 and continued into early 2018, sometimes called the Dey protests. The first protest took place in Mashhad, Iran''s second-largest city by population, initially focused on the economic policies of the country''s government; as protests spread throughout the country, their scope expanded to include political opposition to the theocratic government of Iran and its longtime Supreme Leader, Ali Khamenei.', 2017, 12, 28, 2018, 1, 7, 'day', '28 December 2017 – 7 January 2018', 69, 'https://en.wikipedia.org/wiki/2017%E2%80%932018_Iranian_protests'),
  ('Q47489345', 'Iranian protests against compulsory hijab', 'The Girls of Enghelab protests (Persian: دختران انقلاب, romanized: Dokhtaran Enghalab) are protests against the compulsory hijab in Iran and are part of the wider Iranian Democracy Movement. The protests were inspired by Vida Movahed, an Iranian woman known as the Girl of Enghelab Street (Persian: دختر خیابان انقلاب, romanized: Dokhtar Khiaban Enghalab), who stood above the crowd on a utility box on Enghelab Street (Revolution Street) in Tehran on 27 December 2017 during the 2017–2018 Iranian protests, tying a white headscarf to a stick, and waving it to the crowd as a flag.', 2017, 12, 27, NULL, NULL, NULL, 'day', '27 December 2017', 56, 'https://en.wikipedia.org/wiki/Iranian_protests_against_compulsory_hijab'),
  ('Q56691106', '2018 Ahvaz military parade attack', 'On 22 September 2018, a military parade was attacked by gunmen in the southwestern Iranian city of Ahvaz. The shooters killed 25 people, including soldiers of the Islamic Revolutionary Guard Corps (IRGC) and civilian bystanders.', 2018, 9, 21, NULL, NULL, NULL, 'day', '21 September 2018', 63, 'https://en.wikipedia.org/wiki/Ahvaz_military_parade_attack'),
  ('Q62521190', '2019 Iran Floods', 'From mid-March to April 2019 widespread flash flooding affected large parts of Iran, most severely in Golestan, Fars, Khuzestan, Lorestan, and other provinces. Iran has been hit by three major waves of rain and flooding over the course of two weeks which led to flooding in at least 26 of Iran''s 31 provinces and at least 70 people died nationwide as of 6 April, according to the officials.', 2019, 3, NULL, NULL, NULL, NULL, 'month', 'March 2019', 52, 'https://en.wikipedia.org/wiki/2019_Iran_floods'),
  ('Q75161062', '2019–2020 Iranian protests', 'The 2019–2020 Iranian protests, sometimes known by the protesters as Bloody November or (using the Iranian calendar) Bloody Aban (Persian: آبان خونین), were a series of nationwide civil protests in Iran that took place in 2019 and 2020. Initially caused by a 50–200% increase in fuel prices, they occurred as part of the wider Iranian Democracy Movement, leading to calls for the overthrow of the government in Iran and Supreme Leader Ali Khamenei.', 2019, 11, 15, NULL, NULL, NULL, 'day', '15 November 2019', 61, 'https://en.wikipedia.org/wiki/2019%E2%80%932020_Iranian_protests'),
  ('Q77513637', 'Mahshahr massacre', 'The Mahshahr massacre (Persian: قتل‌عام ماهشهر) refers to the mass killing of protesters in the city of Mahshahr, Iran, which occurred between 16 November and 20 November 2019, during the 2019–2020 Iranian protests. Estimates of fatalities range between 40 and 148.', 2019, 11, 20, 2019, 11, 20, 'day', '20 November 2019', 52, 'https://en.wikipedia.org/wiki/Mahshahr_massacre'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q81341687', '2020 Iranian attack on U.S. forces in Iraq', 'On 8 January 2020, Iran''s Islamic Revolutionary Guard Corps (IRGC) conducted Operation Martyr Soleimani (Persian: عملیات شهید سلیمانی), launching over 12 ballistic missiles against the United States Armed Forces at al-Asad Airbase in Al Anbar Governorate, Iraq, as well as another airbase in Erbil, in response to the assassination of Major General Qasem Soleimani by a U.S. drone strike. The strike was the largest ballistic missile attack ever against U.S. forces abroad.', 2020, 1, 8, NULL, NULL, NULL, 'day', '8 January 2020', 65, 'https://en.wikipedia.org/wiki/Operation_Martyr_Soleimani'),
  ('Q81360866', 'Ukraine International Airlines Flight 752', 'Ukraine International Airlines Flight 752 was a scheduled international passenger flight from Tehran to Kyiv, operated by Ukraine International Airlines. On 8 January 2020, the Boeing 737-800 flying the route was shot down by the Islamic Revolutionary Guard Corps (IRGC) shortly after takeoff, killing all 176 occupants on board.', 2020, 1, 8, NULL, NULL, NULL, 'day', '8 January 2020', 73, 'https://en.wikipedia.org/wiki/Ukraine_International_Airlines_Flight_752'),
  ('Q122962941', 'Gaza War', 'The Gaza war is an armed conflict in the Gaza Strip and Israel, fought as part of the unresolved Israeli–Palestinian and Gaza–Israel conflicts. The war began on 7 October 2023, when Palestinian militant group Hamas led an attack on Israel, in which 1,195 Israelis and foreign nationals were killed and 251 were taken hostage.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 91, 'https://en.wikipedia.org/wiki/Gaza_war'),
  ('Q137612545', '2025–2026 Iranian protests', 'The 2025–2026 Iranian protests were a series of nationwide demonstrations against the government of Iran that began on 28 December 2025 amid a deepening economic crisis. The unrest followed a sharp depreciation of the Iranian rial, rising inflation, and widespread shortages linked to international sanctions and government mismanagement.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 79, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Iranian_protests'),
  ('Q114065797', 'Mahsa Amini protests', 'Civil unrest and protests against the government of the Islamic Republic of Iran associated with the death in police custody of Mahsa Amini (Persian: مهسا امینی) began on 16 September 2022 and carried on into 2023, but by spring 2023, the protests had largely subsided, ultimately leaving the political leadership unchanged and firmly entrenched in power. The protests were described as "unlike any the country had seen before", the "biggest challenge" to the government, and "most widespread revolt" since the Islamic Revolution in 1979.', 2022, NULL, NULL, 2023, 9, NULL, 'year', '2022 – September 2023', 75, 'https://en.wikipedia.org/wiki/Mahsa_Amini_protests'),
  ('Q114868905', '2022 Shah Cheragh attack', 'The Shah Cheragh attack (Persian: حمله به حرم شاه‌چراغ) was a mass shooting that occurred on 26 October 2022 at Shah Cheragh mosque, a Shia pilgrimage site in Shiraz in southern Iran, in which at least 13 people were killed. The Islamic State claimed responsibility for the attack.', 2022, 10, 26, NULL, NULL, NULL, 'day', '26 October 2022', 57, 'https://en.wikipedia.org/wiki/2022_Shah_Cheragh_attack'),
  ('Q128172378', 'assassination of Ismail Haniyeh', 'On 31 July 2024, Ismail Haniyeh, the political leader of Hamas, was assassinated along with his personal bodyguard in the Iranian capital Tehran by an Israeli attack. Haniyeh was killed in his accommodation in a military-run guesthouse after attending the inauguration ceremony for Iranian president Masoud Pezeshkian.', 2024, 7, 31, NULL, NULL, NULL, 'day', '31 July 2024', 69, 'https://en.wikipedia.org/wiki/Assassination_of_Ismail_Haniyeh'),
  ('Q134125330', 'Port of Shahid Rajaee explosion', 'On 26 April 2025, an explosion and fire occurred at the Port of Shahid Rajaee in southern Iran, which is part of Bandar Abbas''s larger port infrastructure, killing 57 people and injuring over 1,000 others, according to state media reports. The blast, at around 12:20 Iran Standard Time, originated from several containers in the port''s wharf area, possibly containing ammonium perchlorate, a strong oxidizer used in rocket fuel.', 2025, 4, 26, NULL, NULL, NULL, 'day', '26 April 2025', 57, 'https://en.wikipedia.org/wiki/Port_of_Shahid_Rajaee_explosion'),
  ('Q134900605', 'Twelve-Day War', 'The Twelve-Day War was an armed conflict between Iran and Israel which lasted from 13 to 24 June 2025. It began when Israel bombed military and nuclear facilities in Iran in a surprise attack, assassinating prominent military leaders, nuclear scientists, and politicians, killing civilians, and damaging or destroying air defenses.', 2025, 6, NULL, 2025, 6, 24, 'month', 'June 2025 – 24 June 2025', 82, 'https://en.wikipedia.org/wiki/Twelve-Day_War'),
  ('Q137703947', '2026 Iran massacres', 'The 2025–2026 Iran massacres were a series of mass killings of civilians by the Iranian government during the 2025–2026 Iranian protests, deploying both its own security forces and importing foreign militias to suppress public dissent nationwide. As of September 2026, most death toll estimates ranged from 5,000 people to over 36,500, including 209 government-affiliated military and non-military personnel, making these among the largest massacres in the modern history of Iran.', 2025, 12, 30, NULL, NULL, NULL, 'day', '30 December 2025', 66, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Iran_massacres'),
  ('Q138505873', '2026 Minab school attack', 'On 28 February 2026, the first day of the 2026 Iran war, the United States (US) Armed Forces struck the Shajareh Tayyebeh Elementary School in Minab, Hormozgan province in southern Iran with a Tomahawk missile, before following up with others in close proximity, directly killing 156 civilians, including 120 schoolchildren and 35 adults. As of 22 September 2026, the attack was the deadliest strike in terms of civilian casualties in the ongoing war; it was also the deadliest US attack on civilians in the 21st century, being the deadliest since the Amiriyah shelter bombing in 1991.', 2026, 2, 28, NULL, NULL, NULL, 'day', '28 February 2026', 66, 'https://en.wikipedia.org/wiki/2026_Minab_school_attack'),
  ('Q138507700', 'assassination of Ali Khamenei', 'On 28 February 2026, Ali Khamenei, the supreme leader of Iran, was assassinated in Tehran as part of a series of Israeli airstrikes aimed at high-ranking Iranian officials. Khamenei''s death was confirmed by the Iranian government on 1 March.', 2026, 2, 28, NULL, NULL, NULL, 'day', '28 February 2026', 70, 'https://en.wikipedia.org/wiki/Assassination_of_Ali_Khamenei');
